<?php require 'config.php';role_required(['dept_head','procurement','director','admin']);$role=user()['role_code'];$map=['dept_head'=>1,'procurement'=>2,'director'=>3];$level=$map[$role]??1;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$rid=(int)$_POST['request_id'];$decision=$_POST['decision'];$comment=trim($_POST['comment']??'');$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT r.*,a.status step_status FROM requests r JOIN approval_steps a ON a.request_id=r.id AND a.level_no=? WHERE r.id=? FOR UPDATE");$s->execute([$level,$rid]);$r=$s->fetch();if(!$r||$r['status']!=='pending'||$r['step_status']!=='pending')throw new Exception(current_lang()==='th'?'รายการนี้ไม่อยู่ในขั้นตอนที่คุณอนุมัติ':'This item is not currently available for your approval.');$pdo->prepare("UPDATE approval_steps SET approver_id=?,status=?,comment=?,acted_at=NOW() WHERE request_id=? AND level_no=?")->execute([user()['id'],$decision,$comment,$rid,$level]);if($decision==='rejected')$pdo->prepare("UPDATE requests SET status='rejected' WHERE id=?")->execute([$rid]);elseif($level<3)$pdo->prepare("UPDATE requests SET current_level=? WHERE id=?")->execute([$level+1,$rid]);else $pdo->prepare("UPDATE requests SET status='approved',current_level=3 WHERE id=?")->execute([$rid]);log_action($rid,user()['id'],'APPROVAL',"$role: $decision $comment");$pdo->commit();flash('ok',current_lang()==='th'?'ดำเนินการเรียบร้อย':'Approval decision saved successfully.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('approvals.php');}$msg=flash();$s=db()->prepare("SELECT r.*,u.name requester FROM requests r JOIN users u ON u.id=r.requester_id JOIN approval_steps a ON a.request_id=r.id AND a.level_no=? WHERE r.status='pending' AND a.status='pending' ORDER BY r.id");$s->execute([$level]);$rows=$s->fetchAll();
foreach($rows as &$row){$it=db()->prepare("SELECT m.code,m.name,m.unit,ri.qty,ri.note,m.price FROM request_items ri JOIN materials m ON m.id=ri.material_id WHERE ri.request_id=?");$it->execute([$row['id']]);$row['items']=$it->fetchAll();}unset($row);?><!doctype html><html lang="<?=e(current_lang())?>"><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-head"><div><h2><?=e(t('approvals'))?> — <?=current_lang()==='th'?'ขั้น':'Level'?> <?=$level?></h2><p><?=e(role_text($role))?> · <?=current_lang()==='th'?'ตรวจสอบและดำเนินการอนุมัติ':'Review and decide pending requisitions'?></p></div></div><?php if($msg):?><div class="alert <?=e($msg[0])?>"><?=e($msg[1])?></div><?php endif;?><?php foreach($rows as $r):?><form method="post" class="approval-card approval-detail-card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="request_id" value="<?=$r['id']?>"><div class="panel-head"><div><h3><?=e($r['request_no'])?></h3><span><?=e(t('requester'))?>: <?=e($r['requester'])?> · <?=e(t('department'))?>: <?=e($r['department'])?></span></div><span class="badge pending"><?=current_lang()==='th'?'รอการอนุมัติ':'Pending'?></span></div><div class="approval-summary"><div><b><?=current_lang()==='th'?'วัตถุประสงค์':'Purpose'?></b><p><?=nl2br(e($r['purpose']))?></p></div></div><div class="table-wrap approval-items"><table class="table"><thead><tr><th><?=e(t('code'))?></th><th><?=e(t('material'))?></th><th><?=e(t('quantity'))?></th><th><?=e(t('unit'))?></th><th><?=e(t('price'))?></th><th><?=e(t('note'))?></th></tr></thead><tbody><?php foreach($r['items'] as $x):?><tr><td><?=e($x['code'])?></td><td><b><?=e($x['name'])?></b></td><td><?=fmt_number($x['qty'])?></td><td><?=e($x['unit'])?></td><td><?=fmt_number($x['price'])?></td><td><?=e($x['note'])?></td></tr><?php endforeach;?></tbody></table></div><label><?=e(t('comment'))?></label><textarea name="comment" placeholder="<?=current_lang()==='th'?'ระบุความเห็น (ถ้ามี)':'Add a comment (optional)'?>"></textarea><div class="approval-actions"><button name="decision" value="approved" class="success">✓ <?=e(t('approve'))?></button><button name="decision" value="rejected" class="danger">✕ <?=e(t('reject'))?></button><a class="btn secondary" href="request_view.php?id=<?=$r['id']?>"><?=e(t('details'))?></a></div></form><?php endforeach;?><?php if(!$rows):?><div class="panel empty"><?=e(t('no_pending'))?></div><?php endif;?></main></div></div></body></html>
